  static Map<String, List<({double lat, double lng, double arv})>>
  getStationsBySect() {
    final map = <String, List<({double lat, double lng, double arv})>>{};
    for (final s in _stations) {
      map.putIfAbsent(s.sect, () => []).add((
        lat: s.lat,
        lng: s.lng,
        arv: s.arv,
      ));
    }
    return map;
  }

  static List<({double lat, double lng, double arv})>? getStationsForSect(
    String sect,
  ) {
    return getStationsBySect()[sect];
  }

  static List<({String name, double lat, double lng, String sect, double arv})>
  getStations() {
    return List.unmodifiable(_stations);
  }

  static String? getSectForStation(String stationName) {
    for (final s in _stations) {
      if (s.name == stationName) return s.sect;
    }
    final normalized = _normalizeStationName(stationName);
    if (normalized == stationName) return null;
    for (final s in _stations) {
      if (_normalizeStationName(s.name) == normalized) return s.sect;
    }
    return null;
  }

  static String _normalizeStationName(String value) {
    return value.trim().replaceAll('\u3000', '').replaceAll(RegExp(r'\s+'), '');
  }
}
